import json,pathlib,html
from content import SCENES
from illustrations import human,robot
p=pathlib.Path(__file__).resolve().parent
TIMINGS=json.loads((p/'timings.json').read_text());total=round(sum(x['duration'] for row in TIMINGS for x in row),3)
CSS='''@font-face{font-family:Paper;src:url(assets/body.ttf)}@font-face{font-family:Paper;src:url(assets/bold.ttf);font-weight:700}*{box-sizing:border-box}html,body{width:1920px;height:1080px;margin:0;overflow:hidden;background:#F4E9D5;color:#302B32;font-family:Paper}.clip{position:absolute;inset:0;width:100%;height:100%}.scene-content{width:100%;height:100%;padding:65px 100px 205px;display:flex;flex-direction:column;gap:22px}.eyebrow{font-size:28px;font-weight:700;letter-spacing:2px;color:#AE3047}.headline{font-size:66px;line-height:1.18;margin:0;font-weight:700;max-width:1660px}.stage{flex:1;min-height:0;display:flex;gap:35px;align-items:center}.person{width:245px;height:350px;flex-shrink:0;transform:rotate(-2deg)}.robot{width:170px;flex-shrink:0;align-self:flex-end}.viz{flex:1;min-width:0;display:flex;align-items:center;gap:24px}.card{flex:1;min-width:0;border:5px solid #302B32;border-radius:7px 15px 9px 12px;box-shadow:8px 9px 0 #302B3218;padding:28px 22px;min-height:245px;display:flex;flex-direction:column;justify-content:center;gap:22px;background:#F7E5AC;transform:rotate(-1.5deg)}.card:nth-child(2){background:#D3E4D3;transform:rotate(1.5deg)}.card:nth-child(3){background:#EBCFD5;transform:rotate(-1deg)}.big{font-size:53px;line-height:1.1;font-weight:700;color:#AE3047;overflow-wrap:normal}.label{font-size:31px;line-height:1.35;font-weight:700}.hero .big{font-size:123px;letter-spacing:-4px}.hero .card{min-height:300px}.flow .big{font-size:66px}.flow .card{min-height:280px}.note{font-size:28px;line-height:1.35;min-height:70px;max-width:1680px}.subtitle.clip{position:absolute;inset:auto auto 48px 0;height:auto;width:100%;padding:0 140px;font-size:36px;line-height:1.4;font-weight:700;text-align:center}.floor{position:absolute;left:0;top:875px;width:100%;height:3px;background:#302B32}.progress{position:absolute;bottom:0;left:0;width:1920px;height:7px;background:#AE3047;transform-origin:left}.sun{position:absolute;top:70px;right:90px;width:140px;height:140px;border-radius:50%;background:#E5C56D;opacity:.25}.bars,.ranks{flex-direction:column;align-items:stretch;gap:28px}.bar-row{display:flex;flex-direction:column;gap:12px}.bar-top{display:flex;justify-content:space-between;align-items:center;font-size:32px;font-weight:700;gap:20px}.bar-value{color:#AE3047;font-size:42px;white-space:nowrap}.bar-track{height:32px;border:4px solid #302B32;border-radius:6px;background:#F4E9D5}.bar-fill{height:100%;background:#AE3047;transform-origin:left;border-radius:2px}.rank{display:flex;gap:28px;align-items:center;border-bottom:3px solid #302B3244;padding:10px 0}.rank strong{font-size:44px;color:#AE3047}.rank span{font-size:36px;font-weight:700}.split .card:first-child{flex:1;background:#F7E5AC}.split .card:last-child{flex:1.4;background:#D3E4D3}.split .big{font-size:105px}.split .card{min-height:300px}'''
parts=[];anim=[];srt=[];script=[];cursor=0
esc=html.escape
for i,s in enumerate(SCENES):
 start=round(cursor,3);duration=round(sum(a['duration'] for a in TIMINGS[i]),3);kind=s['kind'];bg=['#F4E9D5','#DDE9DF','#EEE0DC','#DDD8E5'][i%4]
 if kind=='bars':
  content=''.join(f'<div class="bar-row"><div class="bar-top"><span>{esc(a)}</span><strong class="bar-value">{esc(b)}</strong></div><div class="bar-track"><div class="bar-fill" style="width:{v*100}%"></div></div></div>' for a,b,v in s['items'])
 elif kind=='ranks':
  content=''.join(f'<div class="rank"><strong>{esc(a)}</strong><span>{esc(b)}</span></div>' for a,b in s['items'])
 else:
  content=''.join(f'<div class="card"><strong class="big">{esc(a)}</strong><span class="label">{esc(b)}</span></div>' for a,b in s['items'])
 parts.append(f'<section id="s{i}" class="clip" data-start="{start}" data-duration="{duration+.4 if i<len(SCENES)-1 else duration}" data-track-index="{i}" style="background:{bg};z-index:{i}"><div class="sun" data-layout-ignore></div><div class="scene-content"><div class="eyebrow">{esc(s["kicker"])}</div><h1 class="headline">{esc(s["title"])}</h1><div class="stage">{human()}<div class="viz {kind}">{content}</div>{robot()}</div><div class="note">{esc(s["note"])}</div></div><div class="floor" data-layout-ignore></div></section>')
 anim.append(f'tl.from("#s{i}",{{opacity:0,duration:.4,ease:"sine.inOut"}},{start});tl.from("#s{i} .eyebrow",{{opacity:0,x:-25,duration:.4,ease:"power2.out"}},{start+.15});tl.from("#s{i} .headline",{{opacity:0,y:25,duration:.6,ease:"power3.out"}},{start+.3});tl.from("#s{i} .person",{{opacity:0,x:-35,duration:.65,ease:"back.out(1.4)"}},{start+.45});tl.from("#s{i} .note",{{opacity:0,y:15,duration:.5,ease:"sine.out"}},{start+1.1});tl.from("#s{i} .robot",{{opacity:0,scale:.7,duration:.6,ease:"bounce.out"}},{start+.9});')
 if kind=='bars':anim.append(f'tl.from("#s{i} .bar-row",{{opacity:0,y:25,stagger:.2,duration:.5,ease:"power2.out"}},{start+.6});tl.from("#s{i} .bar-fill",{{scaleX:0,stagger:.25,duration:1,ease:"power3.out"}},{start+.9});')
 elif kind=='ranks':anim.append(f'tl.from("#s{i} .rank",{{opacity:0,x:35,stagger:.25,duration:.6,ease:"back.out(1.2)"}},{start+.6});')
 else:anim.append(f'tl.from("#s{i} .card",{{opacity:0,y:35,stagger:.25,duration:.65,ease:"back.out(1.2)"}},{start+.65});')
 for j,t in enumerate(TIMINGS[i]):
  a=round(cursor,3);b=round(cursor+t['duration'],3)
  parts.append(f'<div id="c{i}-{j}" class="clip subtitle" data-start="{a}" data-duration="{t["duration"]}" data-track-index="100" style="z-index:1000">{esc(t["caption"])}</div>')
  def stamp(v):
   ms=round(v*1000);return f'{ms//3600000:02}:{ms//60000%60:02}:{ms//1000%60:02},{ms%1000:03}'
  srt.append(f'{len(srt)+1}\n{stamp(a)} --> {stamp(b)}\n{t["caption"]}\n');cursor=b
 script.append(s['title']+'\n'+'\n'.join(s['subs']))
(p/'phu-de.srt').write_text('\n'.join(srt));(p/'kich-ban.txt').write_text('\n\n'.join(script))
audio=f'<audio id="narration" src="assets/thuyet-minh.mp3" data-start="0" data-duration="{total}" data-track-index="110" data-volume="1"></audio><audio id="music" src="assets/nhac-nen.mp3" data-start="0" data-duration="{total}" data-track-index="111" data-volume="1"></audio>'
(p/'index.html').write_text(f'<!doctype html><html lang="vi"><head><meta charset="utf-8"><script src="assets/gsap.min.js"></script><style>{CSS}</style></head><body><main id="root" data-composition-id="main" data-start="0" data-duration="{total}" data-width="1920" data-height="1080">'+''.join(parts)+audio+'<div class="progress" style="z-index:1100"></div></main><script>window.__timelines=window.__timelines||{};const tl=gsap.timeline({paused:true});'+''.join(anim)+f'tl.from(".progress",{{scaleX:0,duration:{total},ease:"none"}},0);window.__timelines.main=tl;</script></body></html>')
(p/'meta.json').write_text(json.dumps({'id':p.name,'name':SCENES[0]['title']},ensure_ascii=False,indent=2)+'\n')
print('Duration:',total)
